async function s1SearchMembers(retry=false){
 const form=s1Form(),query=teamQuery.trim();if(!form||!query||form.dataset.saving==='true')return;
 if(!retry&&s1MemberSearch.form===form&&s1MemberSearch.query===query)return;
 const generation=++s1MemberSearch.generation,author=staffProfile;
 Object.assign(s1MemberSearch,{form,query,phase:'loading',ids:[]});
 if(retry){teamOpen=true;$('#interview-team-search').focus()}
 const matches=s1PreviousMatches().filter(m=>m.id!==author).map(m=>m.id);
 updateTeamPicker();
 try{
  const ids=await mockRequest('searchMembers',()=>matches);
  if(generation!==s1MemberSearch.generation||s1Form()!==form||staffProfile!==author||teamQuery.trim()!==query)return;
  Object.assign(s1MemberSearch,{phase:'ready',ids});
 }catch(error){
  if(generation!==s1MemberSearch.generation||s1Form()!==form||staffProfile!==author||teamQuery.trim()!==query)return;
  Object.assign(s1MemberSearch,{phase:'error',ids:[]});
 }
 if(generation===s1MemberSearch.generation&&s1Form()===form)updateTeamPicker();
}
