 if(s1MemberSearch.phase!=='ready'||!query){list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')}
 $('#team-status').textContent=message||teamSelection.length+' selected · ไม่นับผู้จัดนัด';
