function s1PaintCreate(op){
 if(!s1Current(op))return;
 const frozen=['saving','unknown','reading','read-error'].includes(op.phase);
 op.form.dataset.saving=String(frozen);
 for(const [control,disabled]of op.controls)control.disabled=frozen||disabled;
 op.button.setAttribute('aria-busy',String(op.phase==='saving'));
 op.button.innerHTML=op.phase==='saving'?saveSpinner()+'Saving…':op.buttonLabel;
 const box=$('#form-error');box.setAttribute('role',['unknown','write-error','read-error'].includes(op.phase)?'alert':'status');box.setAttribute('tabindex','-1');
 const messages={saving:saveSpinner()+' กำลังบันทึกนัดและทีม…',unknown:'ยังยืนยันผลการบันทึกไม่ได้ ข้อมูลเดิมถูกเก็บไว้ กรุณาลองคำขอเดิมอีกครั้งก่อนแก้ไข <button type="button" onclick="s1RetryCreate()">ลองบันทึกคำขอเดิมอีกครั้ง</button>',reading:saveSpinner()+' บันทึกแล้ว กำลังโหลดข้อมูลล่าสุด…','write-error':'บันทึกนัดและทีมไม่สำเร็จ ข้อมูลที่กรอกยังอยู่ แก้ไขหรือลองบันทึกอีกครั้ง','read-error':'บันทึกแล้ว แต่โหลดข้อมูลล่าสุดไม่สำเร็จ <button type="button" onclick="s1RetryReadback()">ลองโหลดข้อมูลล่าสุดอีกครั้ง</button>'};
 box.innerHTML='<div class="'+(['unknown','write-error','read-error'].includes(op.phase)?'error':'help')+'">'+messages[op.phase]+'</div>';
 if(['unknown','write-error','read-error'].includes(op.phase))box.focus();
}
function s1CreateKey(op){return op.namespace+':'+op.author+':'+op.requestId}
async function s1RunCreate(op){
 if(!s1Current(op)||['saving','reading'].includes(op.phase))return;
 op.phase='saving';s1PaintCreate(op);
 const outcome=mockSavePreview.s1Outcome;mockSavePreview.s1Outcome='success';
 try{
  await mockRequest('write',()=>{
   if(!s1Current(op))throw Error('Identity or form changed');
   if(outcome==='meeting-unknown-uncommitted')throw Object.assign(Error('Unknown response'),{unknown:true});
   const key=s1CreateKey(op);if(!s1CreatedMeetings.has(key))s1CreatedMeetings.set(key,structuredClone(op.payload));
   if(outcome==='meeting-unknown-committed')throw Object.assign(Error('Unknown response'),{unknown:true});
  });
 }catch(error){if(s1Current(op)){op.phase=error.unknown?'unknown':'write-error';s1PaintCreate(op)}return}
 if(s1Current(op))await s1Readback(op);
}
async function s1Readback(op){
 if(!s1Current(op))return;op.phase='reading';s1PaintCreate(op);
 try{
  const saved=await mockRequest('readMeeting',()=>structuredClone(s1CreatedMeetings.get(s1CreateKey(op))));
  if(!s1Current(op))return;if(!saved)throw Error('Readback unavailable');
  if(!records.some(x=>x.id===saved.id)){records.unshift(saved);staffDemoProfiles[op.author].allowed.push(saved.id)}
  op.phase='complete';selected=saved.id;chosenDate=saved.date;weekStart=monday(saved.date);sectionPages={upcoming:1,cancelledRejected:1,past:1};state='normal';notice='สร้างนัดและทีมแล้ว';previewMessage='S1 browser-only simulation · no DB/API/provider';go('detail');
 }catch(error){if(s1Current(op)){op.phase='read-error';s1PaintCreate(op)}}
}
function s1RetryCreate(){const op=s1CreateOperation;if(op?.phase==='unknown')void s1RunCreate(op)}
function s1RetryReadback(){const op=s1CreateOperation;if(op?.phase==='read-error')void s1Readback(op)}
