 const payload={};for(const key of ['name','role','title','date','start','end','status','type','location','description','notes'])payload[key]=$('#'+key).value.trim();
 payload.endDate=$('#end-date').value.trim();payload.email=$('#candidate-email').value.trim();payload.location=payload.location||null;payload.provider='';payload.meetingUrl='';
 const errors=meetingFormErrors(payload);showMeetingErrors(errors);if(Object.keys(errors).length)return;
 Object.assign(payload,{id:Date.now(),organizerId:staffProfile,team:s1SelectedMembers().map(m=>m.email).join(', '),interviewNotes:'',notesByAuthor:{},notesDraftByAuthor:{},feedback:[],history:[],calendar:null});
 const button=form.querySelector('button[type="submit"]');
 s1CreateOperation={form,author:staffProfile,namespace:mockSaveKey,requestId:crypto.randomUUID(),payload:structuredClone(payload),phase:'idle',button,buttonLabel:button.innerHTML,controls:[...form.querySelectorAll('input,select,textarea,button')].map(el=>[el,el.disabled])};
 await s1RunCreate(s1CreateOperation);
